public MainForm(GameSettings settings)          {              _currentSettings = settings ?? new GameSettings();              _currentSettings.Normalize();                // Apply settings              _singlePlayer = _currentSettings.SinglePlayer;              _maxScore = _currentSettings.MaxScore;              _paddleSpeed = _currentSettings.PaddleSpeed;              _ballSpeed = _currentSettings.BallSpeed;              _maxBounceAngleDeg = _currentSettings.MaxBounceAngleDeg;              _maxBallSpeed = _currentSettings.MaxBallSpeed;              _paddleHeight = _currentSettings.PaddleHeight;              _normalPaddleHeight = _paddleHeight; // base height used for scaling                // Power-ups config              _powerUpDurationFrames = _currentSettings.PowerUpDurationSec * FPS;              _powerUpIntervalFrames = _currentSettings.PowerUpSpawnIntervalSec * FPS;              _framesUntilNextPowerUp = _powerUpIntervalFrames;                // Window styling & DPI              Text = "Pong – WinForms";              BackColor = Color.Black;              AutoScaleMode = AutoScaleMode.Dpi; // High-DPI scaling              ClientSize = new Size(_currentSettings.WindowWidth, _currentSettings.WindowHeight);              FormBorderStyle = FormBorderStyle.FixedSingle;              MaximizeBox = false;              StartPosition = FormStartPosition.CenterScreen;                // Double buffering              SetStyle(ControlStyles.AllPaintingInWmPaint |                       ControlStyles.OptimizedDoubleBuffer |                       ControlStyles.UserPaint, true);              UpdateStyles();                // Menu              CreateMenu();                // Timer              _timer.Interval = 1000 / FPS;              _timer.Tick += GameLoop;                // Keyboard              KeyPreview = true;              KeyDown += OnKeyDown;              KeyUp += OnKeyUp;                // Sound              _sound = new SoundManager(_currentSettings.SoundEnabled);                // Determine network role from settings              _netRole = _currentSettings.NetworkMode switch              {                  NetMode.Host => NetRole.Host,                  NetMode.Client => NetRole.Client,                  _ => NetRole.Offline              };                // If networked, force two-player (host authoritative, no AI)              if (_netRole != NetRole.Offline) _singlePlayer = false;                if (_netRole != NetRole.Offline)              {                  string hostIp = _currentSettings.HostIp;                  int port = _currentSettings.NetPort;                    _net = new PongNet(_netRole, hostIp, port);                  _net.OnInput += m => { _remoteUp = m.Up; _remoteDown = m.Down; };                  _net.OnState += s => { _latestState = s; };                  _net.OnInfo += msg => SafeUI(() => Text = $"Pong – {msg}");                    _net.OnError += err => SafeUI(() => MessageBox.Show(err, "Network", MessageBoxButtons.OK, MessageBoxIcon.Warning));                  _net.OnPeerDisconnected += () => SafeUI(() =>                  {                      MessageBox.Show("Verbinding verbroken.", "Network", MessageBoxButtons.OK, MessageBoxIcon.Information);                      _net?.Dispose();                      _netRole = NetRole.Offline;                      Text = "Pong – WinForms";                  });                    //_net.Start();                    // Host: show local IPv4 to share with client                  if (_netRole == NetRole.Host)                  {                      var ips = PongNet.GetLocalIPv4();                      if (ips.Length > 0)                      {                          SafeUI(() =>                              MessageBox.Show($"Host actief op poort {port}
Jouw IP-adres(sen):
 - " + string.Join("
 - ", ips),                                  "Host info", MessageBoxButtons.OK, MessageBoxIcon.Information));                      }                  }                }                // Init objects              ResetPaddles();              StartNewRound(serveToRight: _rng.Next(2) == 0);                // Start fullscreen if requested              if (_currentSettings.StartFullscreen) ToggleFullscreen(force: true);                _timer.Start();          }

